//! HashContext state export/import (`__serialize` / `__unserialize`) checks.
//!
//! The serialisations below come from `ext/hash/tests/hash_serialize_003.phpt`
//! (generated by PHP itself); the error codes from `hash_serialize_004.phpt`
//! and `xxhash_unserialize_memsize.phpt`.

use php_hash::{
    HashOptions, SERIALIZE_MAGIC_SPEC, StateError, StateItem, hash, hash_algos, new_hasher, to_hex,
};

#[derive(Debug)]
enum Value {
    Int(i64),
    Str(Vec<u8>),
    Arr(Vec<Value>),
}

struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl Parser<'_> {
    fn expect(&mut self, s: &str) {
        assert!(
            self.data[self.pos..].starts_with(s.as_bytes()),
            "expected {s:?} at {}",
            self.pos
        );
        self.pos += s.len();
    }

    fn number(&mut self, end: u8) -> i64 {
        let start = self.pos;
        while self.data[self.pos] != end {
            self.pos += 1;
        }
        let n = std::str::from_utf8(&self.data[start..self.pos])
            .unwrap()
            .parse()
            .unwrap();
        self.pos += 1;
        n
    }

    fn value(&mut self) -> Value {
        match self.data[self.pos] {
            b'i' => {
                self.pos += 2;
                Value::Int(self.number(b';'))
            }
            b's' => {
                self.pos += 2;
                let len = self.number(b':') as usize;
                self.expect("\"");
                let s = self.data[self.pos..self.pos + len].to_vec();
                self.pos += len;
                self.expect("\";");
                Value::Str(s)
            }
            b'a' => {
                self.pos += 2;
                let n = self.number(b':');
                self.expect("{");
                let mut items = Vec::new();
                for i in 0..n {
                    // keys are sequential integers
                    assert!(matches!(self.value(), Value::Int(k) if k == i));
                    items.push(self.value());
                }
                self.expect("}");
                Value::Arr(items)
            }
            c => panic!("unexpected {:?}", c as char),
        }
    }
}

fn base64_decode(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let mut acc = 0u32;
    let mut bits = 0;
    for c in s.bytes() {
        let v = match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => continue,
        };
        acc = (acc << 6) | u32::from(v);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((acc >> bits) as u8);
            acc &= (1 << bits) - 1;
        }
    }
    out
}

struct Serialized {
    algo: String,
    options: i64,
    items: Vec<StateItem>,
    magic: i64,
}

fn parse_context(blob: &str) -> Serialized {
    let data = base64_decode(blob);
    let mut p = Parser {
        data: &data,
        pos: 0,
    };
    p.expect("O:11:\"HashContext\":5:{");
    let mut fields = Vec::new();
    for i in 0..5 {
        assert!(matches!(p.value(), Value::Int(k) if k == i));
        fields.push(p.value());
    }
    let mut it = fields.into_iter();
    let (
        Some(Value::Str(algo)),
        Some(Value::Int(options)),
        Some(Value::Arr(state)),
        Some(Value::Int(magic)),
    ) = (it.next(), it.next(), it.next(), it.next())
    else {
        panic!("unexpected HashContext layout");
    };
    let items = state
        .into_iter()
        .map(|v| match v {
            Value::Int(i) => StateItem::Int(i),
            Value::Str(s) => StateItem::Bytes(s),
            Value::Arr(_) => panic!("nested array"),
        })
        .collect();
    Serialized {
        algo: String::from_utf8(algo).unwrap(),
        options,
        items,
        magic,
    }
}

