#[test]
fn serialization_formats_match_php() {
    for (algo, blobs) in SERIALIZATIONS {
        let mut h = new_hasher(algo, &HashOptions::none()).unwrap();
        h.update(FIRST);
        let (magic, items) = h.serialize_state().unwrap();
        let accepted: Vec<Serialized> = blobs.iter().map(|b| parse_context(b)).collect();
        for s in &accepted {
            assert_eq!(s.options, 0, "{algo}");
            assert_eq!(s.algo, h.algorithm().serialized_name, "{algo}");
        }
        let matching = accepted
            .iter()
            .find(|s| s.magic == magic && s.items == items)
            .unwrap_or_else(|| {
                panic!("{algo}: serialisation {items:?} (magic {magic}) not accepted by PHP")
            });

        // The accepted blob unserialises into a context that continues correctly.
        let mut restored = new_hasher(algo, &HashOptions::none()).unwrap();
        restored
            .unserialize_state(matching.magic, &matching.items)
            .unwrap_or_else(|e| panic!("{algo}: unserialize failed: {e}"));
        restored.update(SECOND.as_bytes());
        let mut all = FIRST.to_vec();
        all.extend_from_slice(SECOND.as_bytes());
        assert_eq!(restored.finalize(), hash(algo, &all).unwrap(), "{algo}");
    }
}

#[test]
fn every_serialisable_algorithm_round_trips() {
    for algo in hash_algos() {
        let mut ctx = new_hasher(algo, &HashOptions::none()).unwrap();
        let serial = ctx.serialize_state();
        if matches!(algo, "xxh3" | "xxh128") {
            assert_eq!(serial.unwrap_err(), StateError::Failure, "{algo}");
            continue;
        }
        let (magic, items) = serial.unwrap();
        let mut ctx1 = new_hasher(algo, &HashOptions::none()).unwrap();
        ctx1.unserialize_state(magic, &items).unwrap();
        ctx1.update(FIRST);
        let (magic, items) = ctx1.serialize_state().unwrap();
        let mut ctx2 = new_hasher(algo, &HashOptions::none()).unwrap();
        ctx2.unserialize_state(magic, &items).unwrap();
        ctx.update(FIRST);
        let expected = ctx.finalize();
        assert_eq!(ctx1.finalize(), expected, "{algo}");
        assert_eq!(ctx2.finalize(), expected, "{algo}");
    }
}

#[test]
fn sha1_error_codes_match_php() {
    // hash_serialize_004.phpt: element 6 (a PHP string instead of an int) is C offset 24.
    let sha1_state = |items: Vec<StateItem>| {
        let mut h = new_hasher("sha1", &HashOptions::none()).unwrap();
        h.unserialize_state(SERIALIZE_MAGIC_SPEC, &items)
    };
    let good = {
        let mut h = new_hasher("sha1", &HashOptions::none()).unwrap();
        h.update(FIRST);
        h.serialize_state().unwrap().1
    };
    assert_eq!(sha1_state(good.clone()), Ok(()));

    let mut bad = good.clone();
    bad[6] = StateItem::Bytes(Vec::new());
    let err = sha1_state(bad).unwrap_err();
    assert_eq!(err, StateError::ByteOffset(24));
    assert_eq!(err.code(), -1024);

    // Fewer elements than the spec needs: the first missing one (offset 12) is reported.
    let err = sha1_state(good[..3].to_vec()).unwrap_err();
    assert_eq!(err.code(), -1012);

    // Bad magic number.
    let mut h = new_hasher("sha1", &HashOptions::none()).unwrap();
    let err = h.unserialize_state(0, &good).unwrap_err();
    assert_eq!(err, StateError::Failure);
    assert_eq!(err.code(), -1);

    // Wrong item kind for a byte run.
    let mut bad = good;
    bad[7] = StateItem::Int(0);
    assert_eq!(sha1_state(bad).unwrap_err().code(), -1028);
}

#[test]
fn xxhash_memsize_validation() {
    // xxhash_unserialize_memsize.phpt: memsize beyond the buffer is rejected with -2000.
    let ints = |v: &[i64]| v.iter().map(|&x| StateItem::Int(x)).collect::<Vec<_>>();
    let xxh32 = ints(&[
        0,
        0,
        606290984,
        -2048144777,
        0,
        1640531535,
        0,
        0,
        0,
        0,
        30,
        0,
    ]);
    let mut h = new_hasher("xxh32", &HashOptions::none()).unwrap();
    assert_eq!(
        h.unserialize_state(SERIALIZE_MAGIC_SPEC, &xxh32)
            .unwrap_err()
            .code(),
        -2000
    );
    let xxh64 = ints(&[
        0, 0, 6, 2, 8, 9, 0, 0, 1, 5, 0, 0, 0, 0, 0, 0, 0, 0, 70, 0, 0, 0,
    ]);
    let mut h = new_hasher("xxh64", &HashOptions::none()).unwrap();
    assert_eq!(
        h.unserialize_state(SERIALIZE_MAGIC_SPEC, &xxh64)
            .unwrap_err()
            .code(),
        -2000
    );
}

/// Deterministic pseudo-random bytes (shared with the reference C harness).
fn pattern(seed: u32, n: usize) -> Vec<u8> {
    let mut x = seed;
    (0..n)
        .map(|_| {
            x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            (x >> 24) as u8
        })
        .collect()
}

fn base_state(algo: &str, len: usize) -> Vec<StateItem> {
    let mut h = new_hasher(algo, &HashOptions::none()).unwrap();
    h.update(&pattern(0xabc, len));
    h.serialize_state().unwrap().1
}

fn resume(algo: &str, items: &[StateItem], chunk: &[u8]) -> String {
    let mut h = new_hasher(algo, &HashOptions::none()).unwrap();
    h.unserialize_state(SERIALIZE_MAGIC_SPEC, items).unwrap();
    h.update(chunk);
    to_hex(&h.finalize())
}

/// Hand-crafted contexts that PHP accepts although a normal run never produces
/// them; the expected digests come from PHP's C sources (php-src `ext/hash`).
#[test]
fn crafted_states_behave_like_php() {
    // Whirlpool holding a partial byte (bit-level buffering path).
    let mut it = base_state("whirlpool", 100);
    let n = it.len();
    it[n - 3] = StateItem::Int(63);
    it[n - 2] = StateItem::Int(507);
    assert_eq!(
        resume("whirlpool", &it, &pattern(1, 10)),
        "86e7de0a4ea9bbc34a7303b06c87303eb6a0cf3ab731d82b23ad0f79385485e7704804dddb5d8e193ef86e19dad12d2670a3532dab7854ae1e605f07540b0a28"
    );

    // Whirlpool whose next buffer slot is not clear: the first byte is ORed in.
    let mut it = base_state("whirlpool", 10);
    let n = it.len();
    it[n - 3] = StateItem::Int(10);
    it[n - 2] = StateItem::Int(80);
    if let StateItem::Bytes(b) = &mut it[n - 1] {
        b[10] = 0xff;
    }
    assert_eq!(
        resume("whirlpool", &it, &pattern(2, 5)),
        "b97572b7f51b988d42b2c49ff43ffdfc59e3b1f1caccc5af4f1f495fc9209bc675dfc3e545652d7e110cf8bee5850e12a4c9f436da72146bd3535e64c1c6ccb3"
    );

    // MD5 byte counter beyond 2^29 (`lo` is not masked on import).
    let mut it = base_state("md5", 100);
    it[0] = StateItem::Int(0x6000_0000);
    it[1] = StateItem::Int(3);
    assert_eq!(
        resume("md5", &it, &pattern(3, 100)),
        "237669ecde2a6916bd6cfb8bf760fc3c"
    );

    // xxh64 whose total length disagrees with `memsize`: the tail length is `total_len & 31`.
    let mut it = base_state("xxh64", 40);
    it[0] = StateItem::Int(63);
    it[1] = StateItem::Int(0);
    it[18] = StateItem::Int(0);
    assert_eq!(resume("xxh64", &it, &pattern(4, 7)), "ddff0a0e413bbf0e");

    // The MD5 scratch words are carried through untouched.
    let mut it = base_state("md5", 5);
    let len = it.len();
    for k in 0..16 {
        it[len - 16 + k] = StateItem::Int(k as i64 * 1000 - 5);
    }
    assert_eq!(
        resume("md5", &it, &pattern(5, 3)),
        "08625c81d739f04e92363d62dff75b01"
    );
    let mut h = new_hasher("md5", &HashOptions::none()).unwrap();
    h.unserialize_state(SERIALIZE_MAGIC_SPEC, &it).unwrap();
    assert_eq!(h.serialize_state().unwrap().1, it);
}
